import{_ as e,o,c as r,a2 as s}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"Настройка канала Feishu (Lark)","description":"","frontmatter":{},"headers":[],"relativePath":"ru/integrations/channels/feishu.md","filePath":"ru/integrations/channels/feishu.md","lastUpdated":1792323081000}'),a={name:"ru/integrations/channels/feishu.md"};function n(i,t,l,h,d,g){return o(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="настроика-канала-feishu-lark" tabindex="-1">Настройка канала Feishu (Lark) <a class="header-anchor" href="#настроика-канала-feishu-lark" aria-label="Permalink to &quot;Настройка канала Feishu (Lark)&quot;">​</a></h1><p>Подключите своего Bot в Memoh к Feishu (Lark) через Open Platform, чтобы корпоративный Bot общался с пользователями в группах и личных чатах.</p><h2 id="предварительные-условия" tabindex="-1">Предварительные условия <a class="header-anchor" href="#предварительные-условия" aria-label="Permalink to &quot;Предварительные условия&quot;">​</a></h2><ul><li>Аккаунт на <a href="https://open.feishu.cn/app" target="_blank" rel="noreferrer">Feishu Open Platform</a> с правом создавать собственные приложения.</li><li>Bot в Memoh; каналы настраиваются на его вкладке <strong>Platforms</strong>.</li></ul><h2 id="шаги" tabindex="-1">Шаги <a class="header-anchor" href="#шаги" aria-label="Permalink to &quot;Шаги&quot;">​</a></h2><h3 id="_1-в-консоли-feishu-создаите-собственное-приложение" tabindex="-1">1. В консоли Feishu создайте собственное приложение <a class="header-anchor" href="#_1-в-консоли-feishu-создаите-собственное-приложение" aria-label="Permalink to &quot;1. В консоли Feishu создайте собственное приложение&quot;">​</a></h3><ol><li>Откройте <a href="https://open.feishu.cn/app" target="_blank" rel="noreferrer">Feishu Open Platform</a> и войдите.</li><li>Нажмите <strong>Create Custom App</strong>, укажите название и описание, затем нажмите <strong>Create</strong>.</li><li>В левой панели перейдите в <strong>App Settings</strong> &gt; <strong>Credentials &amp; Basic Info</strong>.</li><li>Скопируйте <strong>App ID</strong> и <strong>App Secret</strong>.</li></ol><h3 id="_2-в-консоли-feishu-включите-возможность-bot" tabindex="-1">2. В консоли Feishu включите возможность Bot <a class="header-anchor" href="#_2-в-консоли-feishu-включите-возможность-bot" aria-label="Permalink to &quot;2. В консоли Feishu включите возможность Bot&quot;">​</a></h3><p>Перейдите в <strong>Capabilities</strong> &gt; <strong>Bot</strong> и нажмите <strong>Enable Bot</strong>.</p><h3 id="_3-в-консоли-feishu-настроите-права" tabindex="-1">3. В консоли Feishu настройте права <a class="header-anchor" href="#_3-в-консоли-feishu-настроите-права" aria-label="Permalink to &quot;3. В консоли Feishu настройте права&quot;">​</a></h3><ol><li>Перейдите в <strong>Capabilities</strong> &gt; <strong>Permissions</strong>.</li><li>Найдите и включите как минимум следующие права: <ul><li><code>im:message</code> (получение и отправка сообщений)</li><li><code>im:chat</code> (доступ к информации о групповых чатах)</li></ul></li><li>Если этого требует ваша организация, нажмите <strong>Apply for Permissions</strong>.</li></ol><h3 id="_4-в-memoh-добавьте-канал-feishu-по-умолчанию-постоянное-соединение" tabindex="-1">4. В Memoh добавьте канал Feishu (по умолчанию: постоянное соединение) <a class="header-anchor" href="#_4-в-memoh-добавьте-канал-feishu-по-умолчанию-постоянное-соединение" aria-label="Permalink to &quot;4. В Memoh добавьте канал Feishu (по умолчанию: постоянное соединение)&quot;">​</a></h3><ol><li>Откройте вкладку <strong>Platforms</strong> нужного Bot и добавьте канал <strong>Feishu</strong>.</li><li>Оставьте для <strong>Inbound Mode</strong> значение по умолчанию: <code>websocket</code>.</li><li>Заполните <strong>App ID</strong> и <strong>App Secret</strong>; если вы используете международный Lark, переключите <strong>Region</strong> на <code>lark</code>.</li><li>Нажмите <strong>Save</strong>. Сообщения приходят по <strong>постоянному WebSocket-соединению</strong> Feishu — публичный URL обратного вызова и настройка подписки на события не нужны.</li></ol><h3 id="_5-необязательно-переключитесь-на-режим-webhook" tabindex="-1">5. Необязательно: переключитесь на режим webhook <a class="header-anchor" href="#_5-необязательно-переключитесь-на-режим-webhook" aria-label="Permalink to &quot;5. Необязательно: переключитесь на режим webhook&quot;">​</a></h3><p>Выбирайте этот вариант, только если ваш сервер доступен из интернета и вы предпочитаете обратные вызовы по событиям.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Этот режим требует переходов между Memoh и консолью Feishu: Memoh генерирует URL обратного вызова, который нужно вставить обратно в <strong>Event Subscriptions</strong>, поэтому держите консоль Feishu открытой.</p></div><ol><li>В Memoh установите <strong>Inbound Mode</strong> в <code>webhook</code>; помимо <strong>App ID</strong> и <strong>App Secret</strong> заполните также <strong>Encrypt Key</strong> и <strong>Verification Token</strong> — они должны совпадать с настройками Event Subscriptions в консоли Feishu.</li><li>Нажмите <strong>Save</strong>. Memoh сгенерирует <strong>Webhook Callback URL</strong> — скопируйте его.</li><li>В консоли Feishu перейдите в <strong>App Settings</strong> &gt; <strong>Event Subscriptions</strong>, вставьте URL в поле <strong>Verification URL</strong> и сохраните.</li><li>Добавьте события, например <strong>Receive Message</strong> (<code>im.message.receive_v1</code>).</li></ol><blockquote><p>Официальное руководство: <a href="https://open.feishu.cn/document/client-docs/bot-v3/add-custom-bot" target="_blank" rel="noreferrer">Feishu Custom Bot Guide</a></p></blockquote><h3 id="_6-в-консоли-feishu-опубликуите-приложение" tabindex="-1">6. В консоли Feishu опубликуйте приложение <a class="header-anchor" href="#_6-в-консоли-feishu-опубликуите-приложение" aria-label="Permalink to &quot;6. В консоли Feishu опубликуйте приложение&quot;">​</a></h3><ol><li>Перейдите в <strong>App Release</strong> &gt; <strong>Version Management &amp; Release</strong>.</li><li>Нажмите <strong>Create a Version</strong>, заполните сведения и отправьте на утверждение.</li><li>После утверждения и публикации Bot готов к работе в вашем тенанте.</li></ol><h2 id="учетные-данные" tabindex="-1">Учётные данные <a class="header-anchor" href="#учетные-данные" aria-label="Permalink to &quot;Учётные данные&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Поле</th><th>Описание</th></tr></thead><tbody><tr><td><strong>App ID</strong></td><td>Из раздела <strong>App Settings</strong> &gt; <strong>Credentials &amp; Basic Info</strong> консоли Feishu.</td></tr><tr><td><strong>App Secret</strong></td><td>С той же страницы <strong>Credentials &amp; Basic Info</strong>.</td></tr><tr><td><strong>Region</strong></td><td>Переключите на <code>lark</code>, если используете международный Lark.</td></tr><tr><td><strong>Inbound Mode</strong></td><td><code>websocket</code> (по умолчанию, постоянное соединение) или <code>webhook</code>.</td></tr><tr><td><strong>Encrypt Key</strong></td><td>Только для режима webhook; должен совпадать с настройками Event Subscriptions в консоли Feishu.</td></tr><tr><td><strong>Verification Token</strong></td><td>Только для режима webhook; должен совпадать с настройками Event Subscriptions в консоли Feishu.</td></tr></tbody></table><h2 id="проверка" tabindex="-1">Проверка <a class="header-anchor" href="#проверка" aria-label="Permalink to &quot;Проверка&quot;">​</a></h2><p>Откройте личный чат с Bot в Feishu и отправьте <code>/help</code>. Если Bot ответил списком команд, канал работает.</p><h2 id="групповые-чаты" tabindex="-1">Групповые чаты <a class="header-anchor" href="#групповые-чаты" aria-label="Permalink to &quot;Групповые чаты&quot;">​</a></h2><p>Групповые чаты Feishu поддерживаются. Добавьте Bot в группу и обращайтесь к нему через @-упоминание.</p><h2 id="отключение-и-смена-учетных-данных" tabindex="-1">Отключение и смена учётных данных <a class="header-anchor" href="#отключение-и-смена-учетных-данных" aria-label="Permalink to &quot;Отключение и смена учётных данных&quot;">​</a></h2><p>Отключить или удалить этот канал можно в любой момент на вкладке <strong>Platforms</strong> нужного Bot. Чтобы сменить учётные данные, обновите поля (например, <strong>App Secret</strong>) и сохраните.</p><h2 id="faq" tabindex="-1">Частые вопросы <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;Частые вопросы {#faq}&quot;">​</a></h2><h3 id="app-not-published" tabindex="-1">Канал настроен, но Bot не отвечает <a class="header-anchor" href="#app-not-published" aria-label="Permalink to &quot;Канал настроен, но Bot не отвечает {#app-not-published}&quot;">​</a></h3><p>Собственное приложение сначала нужно опубликовать: в консоли Feishu перейдите в <strong>App Release</strong> &gt; <strong>Version Management &amp; Release</strong>, создайте версию и отправьте её на утверждение. После утверждения и публикации Bot готов к работе в вашем тенанте.</p><h3 id="permission-approval" tabindex="-1">Включение прав требует согласования <a class="header-anchor" href="#permission-approval" aria-label="Permalink to &quot;Включение прав требует согласования {#permission-approval}&quot;">​</a></h3><p>В некоторых организациях права приложений проходят процесс согласования: нажмите <strong>Apply for Permissions</strong> в разделе <strong>Capabilities</strong> &gt; <strong>Permissions</strong>, чтобы отправить запрос.</p>',33)])])}const c=e(a,[["render",n]]);export{u as __pageData,c as default};
